do $$
declare
  v_package jsonb := $l2e_pkg_0313${"activities":[{"blocks":[{"content":{"level":2,"text":"Welcome"},"id":"week-1-welcome-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"This unit is Exploring New and Emerging Digital Technologies (M/618/3683). Across the year you will outline technologies, then explain how people and organisations use them."},"id":"week-1-welcome-p1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"text":"Digital technology changes quickly. Businesses that notice new tools early can improve service, cut cost or stay safe. This lesson is formative practice for LO1 / AC 1.1. It is not Gateway assignment evidence."},"id":"week-1-welcome-p2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"text":"Define digital technology; tell current from emerging; outline mobile, intelligent computing, IoT and cloud; and spot simple business uses.","title":"By the end of this lesson","tone":"info"},"id":"week-1-welcome-objectives","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"callout","version":"0.1.0"},{"content":{"text":"Misconception: learners often treat any new phone as emerging. Extension: ask for one sector where a current tool is still emerging. Discussion: why must businesses adapt? Differentiation: pair write the starter before sharing."},"id":"week-1-welcome-teacher","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"teacher-note","version":"0.1.0"},{"content":{"level":3,"text":"Starter"},"id":"week-1-welcome-starter-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"Quantum computing is still developing and is not widely adopted, so it is emerging.","incorrect":"Emerging technology is still developing or not yet widely used. A common office PC or projector is current."},"formative":true,"options":[{"id":"a","label":"A desktop PC used for word processing in most offices"},{"id":"b","label":"Quantum computing still in limited research and early commercial trials"},{"id":"c","label":"A wired classroom projector that has been in schools for years"},{"id":"d","label":"A paper timetable on a noticeboard"}],"prompt":"Which of these is an example of an emerging digital technology?","questionId":"week-1-welcome-q1","sourceType":"single"},"id":"week-1-welcome-q1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"}],"id":"week-1-welcome","metadata":{"activityType":"Guided learning","difficulty":"standard","estimatedDurationMinutes":8,"href":null,"status":"available","summary":"Meet the unit, then choose one emerging technology example.","title":"Welcome and starter","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"What is digital technology?"},"id":"week-1-digital-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Digital technology uses electronic devices and software to create, store, share or process data."},"id":"week-1-digital-p1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"text":"Devices are the hardware, such as phones, sensors and servers. Software is the programs and apps that tell hardware what to do."},"id":"week-1-digital-p2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"text":"Networks connect devices so they can share data. Data is the information those systems collect, such as a location, a payment or a temperature reading."},"id":"week-1-digital-p3","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"level":3,"text":"Match the description"},"id":"week-1-digital-match-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"categories":[{"id":"mobile","label":"Mobile Technology"},{"id":"cloud","label":"Cloud Computing"},{"id":"iot","label":"Internet of Things"},{"id":"ai","label":"Artificial Intelligence"}],"feedback":{"correct":"Each description now matches the right technology.","incorrect":"Read each description again. Look for device, network, software pattern or internet-delivered resource."},"formative":true,"items":[{"correctCategoryId":"iot","explanation":"","id":"d-iot","label":"Physical objects that collect or share data over a network, often with little manual input","text":"Physical objects that collect or share data over a network, often with little manual input"},{"correctCategoryId":"ai","explanation":"","id":"d-ai","label":"Software that finds patterns, makes predictions or generates content","text":"Software that finds patterns, makes predictions or generates content"},{"correctCategoryId":"cloud","explanation":"","id":"d-cloud","label":"Computing resources such as storage or software delivered over the internet","text":"Computing resources such as storage or software delivered over the internet"},{"correctCategoryId":"mobile","explanation":"","id":"d-mobile","label":"Portable devices and apps used away from a desk, including phones and tablets","text":"Portable devices and apps used away from a desk, including phones and tablets"}],"prompt":"Match each description to the technology. Descriptions are listed in mixed order.","questionId":"week-1-digital-match"},"id":"week-1-digital-match","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"classification","version":"0.1.0"}],"id":"week-1-digital-technology","metadata":{"activityType":"Classification","difficulty":"standard","estimatedDurationMinutes":12,"href":null,"status":"available","summary":"Outline devices, software, networks and data, then match each description to a technology.","title":"What is digital technology?","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"Current vs emerging technologies"},"id":"week-1-ce-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Current technology is already in common use. Most people or organisations in that setting already rely on it."},"id":"week-1-ce-p1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"text":"Emerging technology is still developing, is costly, or is not yet widely adopted. The same product can be current in one sector and emerging in another."},"id":"week-1-ce-p2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"text":"Example: contactless payment is current in many UK shops. A consumer brain-computer headset is still emerging."},"id":"week-1-ce-p3","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"text":"Ask: would most people in this setting already use it this year?"},"id":"week-1-ce-hint","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"hint","version":"0.1.0"},{"content":{"categories":[{"id":"current","label":"Current"},{"id":"emerging","label":"Emerging"}],"feedback":{"correct":"Current tools are already common. Emerging tools are still limited, costly or not widely used.","incorrect":"A smartphone and cloud storage are already common. Driverless cars and quantum computing are not everyday tools yet."},"formative":true,"items":[{"correctCategoryId":"current","explanation":"","id":"ce-desktop","label":"Desktop PC","text":"Desktop PC"},{"correctCategoryId":"current","explanation":"","id":"ce-phone","label":"Smartphone","text":"Smartphone"},{"correctCategoryId":"emerging","explanation":"","id":"ce-driverless","label":"Driverless cars as everyday personal transport","text":"Driverless cars as everyday personal transport"},{"correctCategoryId":"emerging","explanation":"","id":"ce-quantum","label":"Quantum computing","text":"Quantum computing"},{"correctCategoryId":"current","explanation":"","id":"ce-cloud","label":"Cloud storage such as OneDrive or Google Drive","text":"Cloud storage such as OneDrive or Google Drive"},{"correctCategoryId":"current","explanation":"","id":"ce-ai","label":"An AI assistant built into everyday software","text":"An AI assistant built into everyday software"},{"correctCategoryId":"emerging","explanation":"","id":"ce-wearable","label":"A wearable health monitor used by some people but not yet by most","text":"A wearable health monitor used by some people but not yet by most"}],"prompt":"Sort each example as current or emerging for a typical UK college learner in 2026.","questionId":"week-1-ce-sort"},"id":"week-1-ce-sort","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"classification","version":"0.1.0"}],"id":"week-1-current-emerging","metadata":{"activityType":"Classification","difficulty":"standard","estimatedDurationMinutes":12,"href":null,"status":"available","summary":"Explain the difference, then sort examples.","title":"Current versus emerging","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"Mobile technology"},"id":"week-1-mobile-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Mobile technology is computing you can carry. Smartphones and tablets run apps for messaging, maps, learning and work."},"id":"week-1-mobile-p1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"text":"Mobile payments let people tap a phone or watch to pay. GPS gives location for maps, deliveries and safety."},"id":"week-1-mobile-p2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"text":"Mobile banking lets customers check balances, pay bills and approve logins without a branch visit."},"id":"week-1-mobile-p3","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"level":3,"text":"Select the mobile examples"},"id":"week-1-mobile-h2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"categories":[{"id":"mobile","label":"Mobile"},{"id":"not-mobile","label":"Not mobile"}],"feedback":{"correct":"Mobile examples are portable devices, apps, payments or GPS. A desktop or paper form is not.","incorrect":"Look for phones, tablets, apps, tap-to-pay or GPS. A desktop PC and paper records are not mobile technology."},"formative":true,"items":[{"correctCategoryId":"mobile","explanation":"","id":"m-app","label":"A banking app on a smartphone","text":"A banking app on a smartphone"},{"correctCategoryId":"mobile","explanation":"","id":"m-tablet","label":"A tablet used to sign for a parcel","text":"A tablet used to sign for a parcel"},{"correctCategoryId":"mobile","explanation":"","id":"m-tap","label":"Tapping a phone to pay for lunch","text":"Tapping a phone to pay for lunch"},{"correctCategoryId":"mobile","explanation":"","id":"m-gps","label":"Using GPS to find a college campus","text":"Using GPS to find a college campus"},{"correctCategoryId":"not-mobile","explanation":"","id":"m-tower","label":"A desktop tower that never leaves the office","text":"A desktop tower that never leaves the office"},{"correctCategoryId":"not-mobile","explanation":"","id":"m-paper","label":"A printed paper form in a filing cabinet","text":"A printed paper form in a filing cabinet"}],"prompt":"Choose Mobile for every example that is mobile technology. Choose Not mobile for the distractors.","questionId":"week-1-mobile-select"},"id":"week-1-mobile-select","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"classification","version":"0.1.0"}],"id":"week-1-mobile","metadata":{"activityType":"Classification","difficulty":"standard","estimatedDurationMinutes":10,"href":null,"status":"available","summary":"Outline mobile uses, then select the mobile examples.","title":"Mobile technology","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"Intelligent computing"},"id":"week-1-ic-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Intelligent computing is software and machines that can perform tasks that used to need human judgement, such as spotting a pattern or choosing a next step."},"id":"week-1-ic-p1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"text":"Artificial intelligence (AI) is the broad idea. Machine learning is a common method: the system improves by training on examples rather than only following fixed rules."},"id":"week-1-ic-p2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"text":"Automation runs a process with little human input, such as sorting invoices. Robotics uses machines that move or handle objects, sometimes with AI to decide what to do next."},"id":"week-1-ic-p3","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"level":3,"text":"True or false"},"id":"week-1-ic-h2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"correctOptionId":"a","feedback":{"correct":"Machine learning trains on data so the system can improve without rewriting every rule by hand.","incorrect":"Machine learning trains on data so the system can improve without rewriting every rule by hand."},"formative":true,"options":[{"id":"a","label":"True"},{"id":"b","label":"False"}],"prompt":"Machine learning is one way a system can improve by training on examples.","questionId":"week-1-ic-tf1","sourceType":"single"},"id":"week-1-ic-tf1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"Robotics is about machines that move or handle objects. A factory robot is not a wearable, and it may or may not be connected to the internet.","incorrect":"Robotics is about machines that move or handle objects. A factory robot is not a wearable, and it may or may not be connected to the internet."},"formative":true,"options":[{"id":"a","label":"True"},{"id":"b","label":"False"}],"prompt":"Every robot in a factory must also be an internet-connected wearable.","questionId":"week-1-ic-tf2","sourceType":"single"},"id":"week-1-ic-tf2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"a","feedback":{"correct":"Automation is often used for repeated processes such as copying invoice data.","incorrect":"Automation is often used for repeated processes such as copying invoice data."},"formative":true,"options":[{"id":"a","label":"True"},{"id":"b","label":"False"}],"prompt":"Automation can reduce repetitive data-entry work.","questionId":"week-1-ic-tf3","sourceType":"single"},"id":"week-1-ic-tf3","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"Banks already use AI-style pattern detection to flag unusual payments.","incorrect":"Banks already use AI-style pattern detection to flag unusual payments."},"formative":true,"options":[{"id":"a","label":"True"},{"id":"b","label":"False"}],"prompt":"AI can only be used for generating images, never for spotting fraud.","questionId":"week-1-ic-tf4","sourceType":"single"},"id":"week-1-ic-tf4","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"These tools usually support or change tasks. They do not instantly remove every role.","incorrect":"These tools usually support or change tasks. They do not instantly remove every role."},"formative":true,"options":[{"id":"a","label":"True"},{"id":"b","label":"False"}],"prompt":"Intelligent computing always replaces every human job on day one.","questionId":"week-1-ic-tf5","sourceType":"single"},"id":"week-1-ic-tf5","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"}],"id":"week-1-intelligent-computing","metadata":{"activityType":"Knowledge check","difficulty":"standard","estimatedDurationMinutes":10,"href":null,"status":"available","summary":"Outline AI, machine learning, automation and robotics, then judge five statements.","title":"Intelligent computing","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"Internet of Things"},"id":"week-1-iot-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"The Internet of Things (IoT) is a network of physical devices that collect or share data, often with little manual input."},"id":"week-1-iot-p1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"text":"Smart homes use connected lights, speakers and thermostats. Wearables such as a fitness watch are IoT when they send health or activity data."},"id":"week-1-iot-p2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"text":"Industrial IoT uses sensors and machines in warehouses and factories to track stock, temperature or equipment."},"id":"week-1-iot-p3","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"level":3,"text":"Consumer or business IoT?"},"id":"week-1-iot-h2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"categories":[{"id":"consumer","label":"Consumer IoT"},{"id":"business","label":"Business IoT"}],"feedback":{"correct":"Consumer examples are used by people at home or on the move. Business examples support stock, factories or scanning.","incorrect":"A watch, home thermostat or family car is consumer. Warehouse sensors, factory robots and RFID scanners are business."},"formative":true,"items":[{"correctCategoryId":"consumer","explanation":"","id":"iot-watch","label":"Smart watch","text":"Smart watch"},{"correctCategoryId":"consumer","explanation":"","id":"iot-thermo","label":"Smart thermostat in a house","text":"Smart thermostat in a house"},{"correctCategoryId":"business","explanation":"","id":"iot-warehouse","label":"Warehouse sensors","text":"Warehouse sensors"},{"correctCategoryId":"business","explanation":"","id":"iot-robot","label":"Smart factory robot","text":"Smart factory robot"},{"correctCategoryId":"consumer","explanation":"","id":"iot-car","label":"Connected car used by a family","text":"Connected car used by a family"},{"correctCategoryId":"business","explanation":"","id":"iot-rfid","label":"RFID scanner in a stock room","text":"RFID scanner in a stock room"}],"prompt":"Group each example as consumer IoT or business IoT.","questionId":"week-1-iot-groups"},"id":"week-1-iot-groups","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"classification","version":"0.1.0"}],"id":"week-1-iot","metadata":{"activityType":"Classification","difficulty":"standard","estimatedDurationMinutes":10,"href":null,"status":"available","summary":"Outline connected devices, then group consumer and business examples.","title":"Internet of Things","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"Cloud technology"},"id":"week-1-cloud-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Cloud technology delivers computing over the internet instead of only from one local device. Users can often scale up or down as they need."},"id":"week-1-cloud-p1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"text":"SaaS is software you use in a browser or app, such as email. IaaS rents infrastructure such as virtual machines and storage. PaaS gives a ready place to build and run applications."},"id":"week-1-cloud-p2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"text":"Ask who manages the application. If the provider runs the app for you, it is usually SaaS.","title":"Keep it simple","tone":"info"},"id":"week-1-cloud-callout","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"callout","version":"0.1.0"},{"content":{"level":3,"text":"Complete the sentences"},"id":"week-1-cloud-h2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"correctOptionId":"a","feedback":{"correct":"The provider runs the document app. You just use it, which is SaaS.","incorrect":"Google Docs is software delivered as a service, not a sensor network or a ledger."},"formative":true,"options":[{"id":"a","label":"SaaS"},{"id":"b","label":"IoT"},{"id":"c","label":"AI"},{"id":"d","label":"Blockchain"}],"prompt":"Google Docs is an example of ______.","questionId":"week-1-cloud-q1","sourceType":"single"},"id":"week-1-cloud-q1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"You manage the machines. The cloud supplies the infrastructure, which is IaaS.","incorrect":"IaaS is infrastructure: virtual machines, storage and networks."},"formative":true,"options":[{"id":"a","label":"SaaS"},{"id":"b","label":"IaaS"},{"id":"c","label":"NFC"},{"id":"d","label":"A wearable"}],"prompt":"Renting virtual machines and then installing your own software is ______.","questionId":"week-1-cloud-q2","sourceType":"single"},"id":"week-1-cloud-q2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"a","feedback":{"correct":"PaaS supplies the platform so developers can build and run software.","incorrect":"PaaS is a platform for building apps, not a tag, map or local PC."},"formative":true,"options":[{"id":"a","label":"PaaS"},{"id":"b","label":"RFID"},{"id":"c","label":"GPS"},{"id":"d","label":"A desktop tower"}],"prompt":"A hosted environment for building and running an app is ______.","questionId":"week-1-cloud-q3","sourceType":"single"},"id":"week-1-cloud-q3","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"a","feedback":{"correct":"The provider runs the email application. Learners just use it.","incorrect":"Browser email is software as a service."},"formative":true,"options":[{"id":"a","label":"SaaS"},{"id":"b","label":"A barcode"},{"id":"c","label":"Industrial robotics"},{"id":"d","label":"Paper records"}],"prompt":"College email in a browser is closest to ______.","questionId":"week-1-cloud-q4","sourceType":"single"},"id":"week-1-cloud-q4","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"a","feedback":{"correct":"Cloud services are delivered over the internet and can usually scale.","incorrect":"Cloud is internet-delivered computing, not an offline object."},"formative":true,"options":[{"id":"a","label":"Computing resources delivered over the internet"},{"id":"b","label":"A USB stick that never connects to a network"},{"id":"c","label":"A printed staff handbook"},{"id":"d","label":"A calculator with no data connection"}],"prompt":"Which statement best outlines cloud technology?","questionId":"week-1-cloud-q5","sourceType":"single"},"id":"week-1-cloud-q5","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"a","feedback":{"correct":"Extra virtual disks are infrastructure capacity.","incorrect":"Storage capacity is IaaS, not a wearable or a payment tap."},"formative":true,"options":[{"id":"a","label":"IaaS storage"},{"id":"b","label":"A wearable"},{"id":"c","label":"NFC payments"},{"id":"d","label":"Desktop ink"}],"prompt":"A team that only wants extra disk space during exam week is mainly buying ______.","questionId":"week-1-cloud-q6","sourceType":"single"},"id":"week-1-cloud-q6","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"}],"id":"week-1-cloud","metadata":{"activityType":"Knowledge check","difficulty":"standard","estimatedDurationMinutes":10,"href":null,"status":"available","summary":"Outline SaaS, IaaS and PaaS, then complete each sentence.","title":"Cloud technology","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"How businesses use these technologies"},"id":"week-1-ind-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Retail, banking, entertainment and healthcare all use digital tools, but not always the same ones. Choose the best fit for each organisation in this lesson."},"id":"week-1-ind-p1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"categories":[{"id":"mobile","label":"Mobile Technology"},{"id":"iot","label":"Internet of Things"},{"id":"cloud","label":"Cloud Technology"},{"id":"ai","label":"Intelligent computing / AI"}],"feedback":{"correct":"Stock sensors are IoT, phone banking is mobile, streaming is cloud, and scan flags are intelligent computing.","incorrect":"Match the job: sensors (IoT), phone app (mobile), streaming at scale (cloud), pattern spotting (AI)."},"formative":true,"items":[{"correctCategoryId":"iot","explanation":"","id":"org-retail","label":"Retail: sensors track stock on shelves","text":"Retail: sensors track stock on shelves"},{"correctCategoryId":"mobile","explanation":"","id":"org-bank","label":"Banking: customers pay and check balances on a phone","text":"Banking: customers pay and check balances on a phone"},{"correctCategoryId":"cloud","explanation":"","id":"org-ent","label":"Entertainment: films stream to many viewers at once","text":"Entertainment: films stream to many viewers at once"},{"correctCategoryId":"ai","explanation":"","id":"org-health","label":"Healthcare: software flags unusual scans for a clinician to review","text":"Healthcare: software flags unusual scans for a clinician to review"}],"prompt":"Choose the technology that best fits each organisation in this scenario.","questionId":"week-1-ind-orgs"},"id":"week-1-ind-orgs","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"classification","version":"0.1.0"},{"content":{"level":3,"text":"Technology to business example"},"id":"week-1-ind-h2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"categories":[{"id":"cloud","label":"Cloud Computing"},{"id":"iot","label":"IoT"},{"id":"ai","label":"AI"},{"id":"mobile","label":"Mobile Technology"}],"feedback":{"correct":"Streaming is cloud, warehouse sensing is IoT, fraud flags are AI, and phone banking is mobile.","incorrect":"Think about how the example works: streaming, warehouse sensors, pattern detection, or a phone app."},"formative":true,"items":[{"correctCategoryId":"cloud","explanation":"","id":"ex-netflix","label":"Netflix","text":"Netflix"},{"correctCategoryId":"iot","explanation":"","id":"ex-amazon","label":"Amazon warehouse","text":"Amazon warehouse"},{"correctCategoryId":"ai","explanation":"","id":"ex-fraud","label":"Fraud detection","text":"Fraud detection"},{"correctCategoryId":"mobile","explanation":"","id":"ex-bank","label":"Mobile banking","text":"Mobile banking"}],"prompt":"Match each business example to the technology.","questionId":"week-1-ind-match"},"id":"week-1-ind-match","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"classification","version":"0.1.0"}],"id":"week-1-industry","metadata":{"activityType":"Classification","difficulty":"standard","estimatedDurationMinutes":12,"href":null,"status":"available","summary":"Match a technology to each organisation, then match technologies to business examples.","title":"Industry uses","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"Knowledge check"},"id":"week-1-kc-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Use this to check the lesson. It is formative. It does not produce a Gateway grade."},"id":"week-1-kc-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"correctOptionId":"a","feedback":{"correct":"Digital technology combines hardware, software, networks and data.","incorrect":"Look for electronic systems that handle information, not paper-only or brand colour."},"formative":true,"options":[{"id":"a","label":"Devices, software, networks and data used to create or process information"},{"id":"b","label":"Only paper archives in a locked cupboard"},{"id":"c","label":"Only the colour of a company logo"},{"id":"d","label":"Only face-to-face meetings with no devices"}],"prompt":"Which list best defines digital technology?","questionId":"week-1-kc-q1","sourceType":"single"},"id":"week-1-kc-q1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"a","feedback":{"correct":"Adoption depends on cost, skills, risk and regulation.","incorrect":"Adoption depends on cost, skills, risk and regulation."},"formative":true,"options":[{"id":"a","label":"True"},{"id":"b","label":"False"}],"prompt":"A technology can be current in one sector and emerging in another.","questionId":"week-1-kc-q2","sourceType":"single"},"id":"week-1-kc-q2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"a","feedback":{"correct":"Location services on a phone are a mobile technology use.","incorrect":"GPS on a phone is mobile, not a paper map or a ledger."},"formative":true,"options":[{"id":"a","label":"Mobile technology"},{"id":"b","label":"A printed map only"},{"id":"c","label":"Blockchain mining"},{"id":"d","label":"Desktop publishing"}],"prompt":"GPS on a delivery driver's phone is mainly an example of ______.","questionId":"week-1-kc-q3","sourceType":"single"},"id":"week-1-kc-q3","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"categories":[{"id":"current","label":"Current"},{"id":"emerging","label":"Emerging"}],"feedback":{"correct":"Campus Wi-Fi is already common. A rare holographic display is still emerging.","incorrect":"Ask whether most people already use it."},"formative":true,"items":[{"correctCategoryId":"current","explanation":"","id":"kc-wifi","label":"Classroom Wi-Fi","text":"Classroom Wi-Fi"},{"correctCategoryId":"emerging","explanation":"","id":"kc-holo","label":"A personal holographic display that few shops sell","text":"A personal holographic display that few shops sell"}],"prompt":"Sort these two examples.","questionId":"week-1-kc-q4"},"id":"week-1-kc-q4","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"classification","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"IoT devices collect or share data, often automatically, over a network.","incorrect":"IoT devices collect or share data, often automatically, over a network."},"formative":true,"options":[{"id":"a","label":"True"},{"id":"b","label":"False"}],"prompt":"IoT devices never share data over a network.","questionId":"week-1-kc-q5","sourceType":"single"},"id":"week-1-kc-q5","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"a","feedback":{"correct":"Learning from examples to flag unusual payments is intelligent computing.","incorrect":"A basic calculator follows fixed arithmetic. Pattern detection from examples is closer to AI."},"formative":true,"options":[{"id":"a","label":"Software that learns from past payments to flag unusual activity"},{"id":"b","label":"Adding two numbers with a basic handheld calculator"},{"id":"c","label":"A blank notebook"},{"id":"d","label":"A wall clock with no sensors"}],"prompt":"Which option is intelligent computing rather than a simple calculator?","questionId":"week-1-kc-q6","sourceType":"single"},"id":"week-1-kc-q6","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"a","feedback":{"correct":"SaaS is software delivered as a service.","incorrect":"If you just use the app and the provider runs it, that is SaaS."},"formative":true,"options":[{"id":"a","label":"Software you use through a browser or app while the provider runs it"},{"id":"b","label":"A warehouse pallet"},{"id":"c","label":"A paper invoice book"},{"id":"d","label":"A HDMI cable"}],"prompt":"SaaS is best outlined as ______.","questionId":"week-1-kc-q7","sourceType":"single"},"id":"week-1-kc-q7","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"Cloud services are delivered over the internet, not only on one offline laptop.","incorrect":"Cloud services are delivered over the internet, not only on one offline laptop."},"formative":true,"options":[{"id":"a","label":"True"},{"id":"b","label":"False"}],"prompt":"Cloud services can only ever run on one laptop with no internet.","questionId":"week-1-kc-q8","sourceType":"single"},"id":"week-1-kc-q8","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"a","feedback":{"correct":"A tablet on a ward is a portable device used away from a desk.","incorrect":"Mobile technology is used on the move. A locked server or cardboard box is not."},"formative":true,"options":[{"id":"a","label":"A nurse updating a patient note on a tablet on the ward"},{"id":"b","label":"A server that never leaves a locked data centre and has no mobile app"},{"id":"c","label":"A cardboard archive box"},{"id":"d","label":"A desktop-only accounts pack with no network"}],"prompt":"Which business use is the best fit for mobile technology?","questionId":"week-1-kc-q9","sourceType":"single"},"id":"week-1-kc-q9","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"categories":[{"id":"iot","label":"IoT"},{"id":"cloud","label":"Cloud"}],"feedback":{"correct":"Field sensors are IoT. Hosted mailbox software is cloud / SaaS.","incorrect":"Sensors sharing data are IoT. Browser email is cloud software."},"formative":true,"items":[{"correctCategoryId":"iot","explanation":"","id":"kc-soil","label":"Soil sensors sending moisture readings from a field","text":"Soil sensors sending moisture readings from a field"},{"correctCategoryId":"cloud","explanation":"","id":"kc-mail","label":"Staff mailboxes hosted by a provider and opened in a browser","text":"Staff mailboxes hosted by a provider and opened in a browser"}],"prompt":"Match the remaining pair.","questionId":"week-1-kc-q10"},"id":"week-1-kc-q10","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"classification","version":"0.1.0"},{"content":{"text":"Common mix-up: cloud versus IoT. Extension: name one risk if a wearable leaks health data. Discussion: should a college treat AI assistants as current or emerging? Differentiation: allow the classification items to be completed with a partner."},"id":"week-1-kc-teacher","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"teacher-note","version":"0.1.0"}],"id":"week-1-knowledge-check","metadata":{"activityType":"Knowledge check","difficulty":"standard","estimatedDurationMinutes":15,"href":null,"status":"available","summary":"Ten mixed questions. None of these copies an earlier item word for word.","title":"Knowledge check","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"Reflection"},"id":"week-1-ref-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Use one technology from this lesson. Keep the answer short. This is practice, not assignment evidence."},"id":"week-1-ref-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"formative":true,"guidance":"Name the technology, who it could help, and one reason. Write at least 400 characters. Paste is disabled.","minChars":400,"prompt":"Which emerging technology do you believe will have the biggest impact over the next decade and why?","questionId":"week-1-ref-q"},"id":"week-1-ref-q","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"short-response","version":"0.1.0"}],"id":"week-1-reflection","metadata":{"activityType":"Reflection","difficulty":"standard","estimatedDurationMinutes":8,"href":null,"status":"available","summary":"Write a short response on impact over the next decade.","title":"Reflection","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"Exit ticket"},"id":"week-1-exit-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"correctOptionId":"a","feedback":{"correct":"Emerging technology is still developing or not yet in common use.","incorrect":"Electricity alone does not make a tool emerging. Look at adoption and development."},"formative":true,"options":[{"id":"a","label":"Technology that is still developing or not yet widely adopted"},{"id":"b","label":"Any device that has electricity"},{"id":"c","label":"Only software that cannot connect to a network"},{"id":"d","label":"A paper filing system with no computers"}],"prompt":"Which statement is the best outline of emerging digital technology?","questionId":"week-1-exit-q1","sourceType":"single"},"id":"week-1-exit-q1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"formative":false,"options":[{"id":"a","label":"Very unsure"},{"id":"b","label":"Unsure"},{"id":"c","label":"OK"},{"id":"d","label":"Confident"},{"id":"e","label":"Very confident"}],"prompt":"How confident are you that you can outline current versus emerging technology after this lesson?","questionId":"week-1-exit-q2"},"id":"week-1-exit-q2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"formative":true,"guidance":"One sentence is enough, but write at least 80 characters. Paste is disabled.","minChars":80,"prompt":"Write one sentence: which idea from today will you reuse when you outline a technology next week?","questionId":"week-1-exit-q3"},"id":"week-1-exit-q3","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"reflection","version":"0.1.0"}],"id":"week-1-exit-ticket","metadata":{"activityType":"Reflection","difficulty":"standard","estimatedDurationMinutes":6,"href":null,"status":"available","summary":"One multiple-choice check, a confidence rating, and a short reflection.","title":"Exit ticket","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"Welcome to Week 2"},"id":"week-2-starter-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"This week you outline Internet of Things (IoT), connected devices, RFID, NFC and wearables (AC1.1)."},"id":"week-2-starter-p1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"text":"By the end, define each technology, give an example, and note one benefit and one risk."},"id":"week-2-starter-p2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"IoT is a network of physical devices that collect or share data, often automatically.","incorrect":"IoT is a network of physical devices that collect or share data, often automatically."},"formative":true,"options":[{"id":"a","label":"A single desktop PC with no network link"},{"id":"b","label":"Physical devices that collect or share data over a network"},{"id":"c","label":"Printed barcodes that never use radio"},{"id":"d","label":"A paper rota on a noticeboard"}],"prompt":"Which best describes the Internet of Things (IoT)?","questionId":"week-2-starter-q1","sourceType":"single"},"id":"week-2-starter-q1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"}],"id":"week-2-starter","metadata":{"activityType":"Starter","difficulty":"standard","estimatedDurationMinutes":8,"href":null,"status":"available","summary":"Set the focus for AC1.1: outline IoT, connected devices, RFID, NFC and wearables.","title":"Welcome to Week 2","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"IoT and connected devices"},"id":"week-2-iot-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"IoT devices sense, act or share data with little manual input. A connected device can send or receive data over a network (Wi-Fi, mobile, Bluetooth or similar)."},"id":"week-2-iot-p1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"text":"Examples: smart thermostat, warehouse temperature sensor, connected street light, hospital infusion pump that reports status."},"id":"week-2-iot-p2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"Connected devices exchange data over a network.","incorrect":"Connected devices exchange data over a network."},"formative":true,"options":[{"id":"a","label":"Only store data offline with no network path"},{"id":"b","label":"Send or receive data over a network"},{"id":"c","label":"Be made of metal only"},{"id":"d","label":"Print on paper without electronics"}],"prompt":"A device is 'connected' mainly when it can:","questionId":"week-2-iot-q1","sourceType":"single"},"id":"week-2-iot-q1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"Sensors sharing field data are a classic IoT use.","incorrect":"Sensors sharing field data are a classic IoT use."},"formative":true,"options":[{"id":"a","label":"A paper clipboard in a storeroom"},{"id":"b","label":"Soil moisture sensors uploading readings to a farm dashboard"},{"id":"c","label":"A whiteboard marker"},{"id":"d","label":"An unplugged desk lamp with no radio"}],"prompt":"Which is the best IoT example?","questionId":"week-2-iot-q2","sourceType":"single"},"id":"week-2-iot-q2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"}],"id":"week-2-iot","metadata":{"activityType":"Teaching","difficulty":"standard","estimatedDurationMinutes":12,"href":null,"status":"available","summary":"Outline what IoT is and what makes a device 'connected'.","title":"IoT and connected devices","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"Consumer, industrial and healthcare IoT"},"id":"week-2-iot-sectors-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Consumer IoT is for homes and personal use. Industrial IoT supports factories, farms and logistics. Healthcare IoT supports patients and clinical monitoring."},"id":"week-2-iot-sectors-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"categories":[{"id":"consumer","label":"Consumer IoT"},{"id":"industrial","label":"Industrial IoT"},{"id":"healthcare","label":"Healthcare IoT"}],"feedback":{"correct":"Those matches look right.","incorrect":"Check the definition and try again."},"formative":true,"items":[{"correctCategoryId":"consumer","id":"s1","text":"Smart home heating controlled from a phone"},{"correctCategoryId":"industrial","id":"s2","text":"Factory machine vibration sensors for maintenance"},{"correctCategoryId":"healthcare","id":"s3","text":"Wearable heart-rate monitor used in a clinic trial"},{"correctCategoryId":"consumer","id":"s4","text":"Fridge camera helping a household reorder milk"},{"correctCategoryId":"industrial","id":"s5","text":"Cold-store sensors in a warehouse"},{"correctCategoryId":"healthcare","id":"s6","text":"Connected drip pump reporting dose alerts"}],"prompt":"Match each example to the sector.","questionId":"week-2-iot-sectors-q"},"id":"week-2-iot-sectors-q","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"classification","version":"0.1.0"}],"id":"week-2-iot-sectors","metadata":{"activityType":"Classification","difficulty":"standard","estimatedDurationMinutes":12,"href":null,"status":"available","summary":"Classify IoT examples by sector.","title":"Consumer, industrial and healthcare IoT","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"RFID"},"id":"week-2-rfid-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"RFID uses radio tags and readers to identify items. Readers can often scan tags without lining every item up under a camera, which helps stock and asset tracking."},"id":"week-2-rfid-p1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"text":"Typical uses: clothing tags in retail, pallet tags in warehouses, library books, tool tracking on a site."},"id":"week-2-rfid-p2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"correctOptionId":"a","feedback":{"correct":"RFID readers identify tagged items at short range, including when items are not lined up one by one.","incorrect":"RFID readers identify tagged items at short range, including when items are not lined up one by one."},"formative":true,"options":[{"id":"a","label":"Identify tagged items at short distance without lining each one under a camera"},{"id":"b","label":"Replace all radio with paper only"},{"id":"c","label":"Project a hologram in a classroom"},{"id":"d","label":"Run a spreadsheet with no tags"}],"prompt":"RFID is most useful when an organisation needs to:","questionId":"week-2-rfid-q1","sourceType":"single"},"id":"week-2-rfid-q1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"formative":true,"guidance":"Mention tagged items and tracking or scanning. Write at least 100 characters. Paste is disabled.","minChars":100,"prompt":"Give one business use of RFID.","questionId":"week-2-rfid-q2"},"id":"week-2-rfid-q2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"short-response","version":"0.1.0"}],"id":"week-2-rfid","metadata":{"activityType":"Teaching","difficulty":"standard","estimatedDurationMinutes":12,"href":null,"status":"available","summary":"Outline how RFID tags and readers identify items.","title":"RFID principles","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"NFC"},"id":"week-2-nfc-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"NFC (Near Field Communication) is very short-range radio, usually centimetres. It suits short taps such as contactless payment, door badges and ticket gates."},"id":"week-2-nfc-p1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"NFC is for close taps over a few centimetres.","incorrect":"NFC is for close taps over a few centimetres."},"formative":true,"options":[{"id":"a","label":"Satellite distances"},{"id":"b","label":"Very short range (about a few centimetres)"},{"id":"c","label":"Cross-country microwave links only"},{"id":"d","label":"Paper-only delivery"}],"prompt":"NFC is designed to work over:","questionId":"week-2-nfc-q1","sourceType":"single"},"id":"week-2-nfc-q1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"a","feedback":{"correct":"Contactless payment taps use NFC.","incorrect":"Contactless payment taps use NFC."},"formative":true,"options":[{"id":"a","label":"Tapping a phone on a till to pay"},{"id":"b","label":"A weather satellite downlink"},{"id":"c","label":"A printed poster with no electronics"},{"id":"d","label":"A long-range warehouse aisle scan of 200 tagged boxes at once"}],"prompt":"Which is the best NFC example?","questionId":"week-2-nfc-q2","sourceType":"single"},"id":"week-2-nfc-q2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"}],"id":"week-2-nfc","metadata":{"activityType":"Teaching","difficulty":"standard","estimatedDurationMinutes":10,"href":null,"status":"available","summary":"Outline NFC as very short-range radio for secure taps.","title":"NFC principles","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"RFID versus NFC"},"id":"week-2-rfid-vs-nfc-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Both use radio, but NFC is for very close taps. RFID often supports stock/asset tagging where a reader covers a short area and many tags."},"id":"week-2-rfid-vs-nfc-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"categories":[{"id":"rfid","label":"RFID"},{"id":"nfc","label":"NFC"}],"feedback":{"correct":"Those matches look right.","incorrect":"Check the definition and try again."},"formative":true,"items":[{"correctCategoryId":"rfid","id":"v1","text":"Best for scanning many tagged boxes in a stock room"},{"correctCategoryId":"nfc","id":"v2","text":"Best for a phone tap at a payment terminal"},{"correctCategoryId":"rfid","id":"v3","text":"Often used on clothing security tags"},{"correctCategoryId":"nfc","id":"v4","text":"Usually limited to a few centimetres"}],"prompt":"Classify each statement.","questionId":"week-2-rfid-vs-nfc-q"},"id":"week-2-rfid-vs-nfc-q","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"classification","version":"0.1.0"}],"id":"week-2-rfid-vs-nfc","metadata":{"activityType":"Classification","difficulty":"standard","estimatedDurationMinutes":10,"href":null,"status":"available","summary":"Compare RFID and NFC by range and typical use.","title":"RFID versus NFC","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"Wearables"},"id":"week-2-wearables-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Wearables are devices worn on the body: fitness watches, smart badges, medical patches. Many are IoT devices when they upload activity or health data."},"id":"week-2-wearables-p1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"Wearables are worn on the body.","incorrect":"Wearables are worn on the body."},"formative":true,"options":[{"id":"a","label":"A rack server in a data centre"},{"id":"b","label":"A fitness watch counting steps"},{"id":"c","label":"A wall-mounted classroom projector"},{"id":"d","label":"A paper timetable"}],"prompt":"Which is a wearable?","questionId":"week-2-wearables-q1","sourceType":"single"},"id":"week-2-wearables-q1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"Shared sensor data over a network makes it an IoT wearable.","incorrect":"Shared sensor data over a network makes it an IoT wearable."},"formative":true,"options":[{"id":"a","label":"Never leaves airplane mode and never shares data"},{"id":"b","label":"Shares sensor data over a network to an app or service"},{"id":"c","label":"Is made of plastic only"},{"id":"d","label":"Is larger than a fridge"}],"prompt":"A wearable becomes an IoT example mainly when it:","questionId":"week-2-wearables-q2","sourceType":"single"},"id":"week-2-wearables-q2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"}],"id":"week-2-wearables","metadata":{"activityType":"Teaching","difficulty":"standard","estimatedDurationMinutes":10,"href":null,"status":"available","summary":"Outline wearables and how they link to IoT.","title":"Wearable technologies","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"Smart homes, cities and healthcare"},"id":"week-2-smart-settings-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"The same IoT idea appears in homes, cities and healthcare, with different goals: comfort, public services, or patient safety."},"id":"week-2-smart-settings-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"categories":[{"id":"home","label":"Smart home"},{"id":"city","label":"Smart city"},{"id":"health","label":"Healthcare"}],"feedback":{"correct":"Those matches look right.","incorrect":"Check the definition and try again."},"formative":true,"items":[{"correctCategoryId":"home","id":"m1","text":"Connected thermostat learning household routines"},{"correctCategoryId":"city","id":"m2","text":"Street lights that dim when roads are empty"},{"correctCategoryId":"health","id":"m3","text":"Remote monitoring of a patient's oxygen levels"},{"correctCategoryId":"home","id":"m4","text":"Smart door lock for a flat"},{"correctCategoryId":"city","id":"m5","text":"Traffic sensors feeding a live congestion map"},{"correctCategoryId":"health","id":"m6","text":"Hospital bed sensor alerting when a patient leaves the bed"}],"prompt":"Match each example.","questionId":"week-2-smart-settings-q"},"id":"week-2-smart-settings-q","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"classification","version":"0.1.0"}],"id":"week-2-smart-settings","metadata":{"activityType":"Classification","difficulty":"standard","estimatedDurationMinutes":12,"href":null,"status":"available","summary":"Match connected examples to smart home, smart city or healthcare.","title":"Smart homes, cities and healthcare settings","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"Benefits, risks and security"},"id":"week-2-benefits-risks-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Benefits include automation, better decisions from live data, and convenience. Risks include hacking, outages, cost, and poor configuration."},"id":"week-2-benefits-risks-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"Live sensor data helps spot faults and improve decisions.","incorrect":"Live sensor data helps spot faults and improve decisions."},"formative":true,"options":[{"id":"a","label":"Remove the need for any safety rules"},{"id":"b","label":"Provide live data to spot faults earlier"},{"id":"c","label":"Guarantee zero cyber risk"},{"id":"d","label":"Replace all human staff overnight"}],"prompt":"A clear benefit of industrial IoT sensors is that they can:","questionId":"week-2-benefits-risks-q1","sourceType":"single"},"id":"week-2-benefits-risks-q1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"Weak credentials and missing updates are common IoT security risks.","incorrect":"Weak credentials and missing updates are common IoT security risks."},"formative":true,"options":[{"id":"a","label":"They never use electricity"},{"id":"b","label":"Weak passwords or unpatched firmware can be exploited"},{"id":"c","label":"They only work on paper"},{"id":"d","label":"They cannot store any data"}],"prompt":"A key security risk for always-on IoT devices is:","questionId":"week-2-benefits-risks-q2","sourceType":"single"},"id":"week-2-benefits-risks-q2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"}],"id":"week-2-benefits-risks","metadata":{"activityType":"Knowledge check","difficulty":"standard","estimatedDurationMinutes":10,"href":null,"status":"available","summary":"Check benefits of connected tech and key security risks.","title":"Benefits, risks and security","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"Privacy and real-world cases"},"id":"week-2-privacy-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Wearables and healthcare IoT often handle sensitive data. Organisations need consent, clear purpose, access control and secure storage."},"id":"week-2-privacy-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"Leaked health data is a privacy and consent issue.","incorrect":"Leaked health data is a privacy and consent issue."},"formative":true,"options":[{"id":"a","label":"Faster Wi-Fi only"},{"id":"b","label":"Private health details exposed without consent"},{"id":"c","label":"Larger fonts on the screen"},{"id":"d","label":"Longer battery life"}],"prompt":"Main privacy risk if a fitness wearable leaks heart-rate data?","questionId":"week-2-privacy-q1","sourceType":"single"},"id":"week-2-privacy-q1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"formative":true,"guidance":"Write 2-4 short sentences (at least 350 characters). Paste is disabled. This is practice only.","minChars":350,"prompt":"Outline one real-world case: name the technology (IoT, RFID, NFC or wearable), who uses it, and one risk to manage.","questionId":"week-2-privacy-q2"},"id":"week-2-privacy-q2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"short-response","version":"0.1.0"}],"id":"week-2-privacy","metadata":{"activityType":"Application","difficulty":"standard","estimatedDurationMinutes":12,"href":null,"status":"available","summary":"Consider privacy implications and outline a short case study.","title":"Privacy and case study thinking","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"Emerging trends"},"id":"week-2-trends-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Trends include more sensors in cities, tighter security expectations, edge processing on devices, and wearables used in workplace health programmes."},"id":"week-2-trends-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"Security and update expectations for IoT are rising.","incorrect":"Security and update expectations for IoT are rising."},"formative":true,"options":[{"id":"a","label":"All IoT devices will stop using networks"},{"id":"b","label":"More organisations expect stronger IoT security and updates"},{"id":"c","label":"RFID will only work on the Moon"},{"id":"d","label":"NFC will replace all long-distance radio"}],"prompt":"Which statement is a realistic emerging trend?","questionId":"week-2-trends-q1","sourceType":"single"},"id":"week-2-trends-q1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"}],"id":"week-2-trends","metadata":{"activityType":"Knowledge check","difficulty":"standard","estimatedDurationMinutes":8,"href":null,"status":"available","summary":"Spot sensible near-term trends for connected devices.","title":"Emerging trends","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"Portfolio reflection"},"id":"week-2-reflection-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Write one example each for IoT, RFID, NFC and wearables. This is practice only, not Gateway assignment evidence."},"id":"week-2-reflection-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"formative":true,"guidance":"Cover all four technologies and one benefit plus one risk. Write at least 500 characters. Paste is disabled.","minChars":500,"prompt":"List one example for IoT, RFID, NFC and wearables. For one of them, add one benefit and one privacy or security risk.","questionId":"week-2-reflection-q"},"id":"week-2-reflection-q","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"reflection","version":"0.1.0"}],"id":"week-2-reflection","metadata":{"activityType":"Reflection","difficulty":"standard","estimatedDurationMinutes":10,"href":null,"status":"available","summary":"Write a short note covering the Week 2 technologies.","title":"Portfolio reflection","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.1"},{"blocks":[{"content":{"level":2,"text":"Exit ticket"},"id":"week-2-exit-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"RFID identifies tagged items; NFC is for close taps.","incorrect":"RFID identifies tagged items; NFC is for close taps."},"formative":true,"options":[{"id":"a","label":"NFC = long-range satellite; RFID = paper only"},{"id":"b","label":"RFID = tagged item identification; NFC = very short-range tap"},{"id":"c","label":"Wearable = data-centre rack; IoT = printed poster"},{"id":"d","label":"IoT = no network; NFC = continental radio"}],"prompt":"Which pair is correct?","questionId":"week-2-exit-q1","sourceType":"single"},"id":"week-2-exit-q1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"c","feedback":{"correct":"Aim to define each technology, give a use, and note a risk.","incorrect":"Aim to define each technology, give a use, and note a risk."},"formative":true,"options":[{"id":"a","label":"Not yet. I need another look at the definitions."},{"id":"b","label":"Getting there. I can give one example for most."},{"id":"c","label":"Confident. I can define each and give a use plus a risk."},{"id":"d","label":"I can teach it to a classmate tomorrow"}],"prompt":"How confident are you with IoT, RFID, NFC and wearables?","questionId":"week-2-exit-q2","sourceType":"single"},"id":"week-2-exit-q2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"}],"id":"week-2-exit","metadata":{"activityType":"Exit ticket","difficulty":"standard","estimatedDurationMinutes":6,"href":null,"status":"available","summary":"Quick check: can you outline the Week 2 technologies?","title":"Exit ticket","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"Welcome to Week 3"},"id":"week-3-starter-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"This week you outline cloud technology and distinguish SaaS, IaaS, PaaS and DaaS (AC1.1)."},"id":"week-3-starter-p1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"text":"By the end, define cloud computing, match everyday services to a model, and write a short cloud profile."},"id":"week-3-starter-p2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"Connected devices often keep a local copy and also send data to cloud services so it can be viewed later on other devices.","incorrect":"Connected devices often keep a local copy and also send data to cloud services so it can be viewed later on other devices."},"formative":true,"options":[{"id":"a","label":"Only inside the watch with no other copy"},{"id":"b","label":"Often on remote servers accessed over the internet (the cloud), as well as on the device"},{"id":"c","label":"Only on a printed paper chart"},{"id":"d","label":"Only in a classroom USB stick that never connects"}],"prompt":"A fitness watch from Week 2 uploads heart-rate readings to an app account. Where is that health data mainly stored for later viewing?","questionId":"week-3-starter-q1","sourceType":"single"},"id":"week-3-starter-q1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"}],"id":"week-3-starter","metadata":{"activityType":"Starter","difficulty":"standard","estimatedDurationMinutes":8,"href":null,"status":"available","summary":"Retrieve where data lives, then set the focus for cloud service models (AC1.1).","title":"Welcome to Week 3","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"What is cloud technology?"},"id":"week-3-cloud-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Cloud technology delivers computing resources over the internet instead of only from one local device or a single on-site server. Users can often scale up or down and pay for what they use."},"id":"week-3-cloud-p1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"text":"Examples include web email, online file storage, rented virtual machines, hosted app platforms and remote desktops."},"id":"week-3-cloud-p2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"correctOptionId":"a","feedback":{"correct":"Cloud means resources are delivered over the internet and can usually grow or shrink with demand.","incorrect":"Cloud means resources are delivered over the internet and can usually grow or shrink with demand."},"formative":true,"options":[{"id":"a","label":"Computing resources delivered over the internet, often scaled as needed"},{"id":"b","label":"A single USB stick that never connects to a network"},{"id":"c","label":"Only paper filing cabinets in one office"},{"id":"d","label":"A projector that cannot store or share files"}],"prompt":"Which statement best outlines cloud technology?","questionId":"week-3-cloud-q1","sourceType":"single"},"id":"week-3-cloud-q1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"If the file stays only on that PC, it is local storage, not cloud storage.","incorrect":"If the file stays only on that PC, it is local storage, not cloud storage."},"formative":true,"options":[{"id":"a","label":"Cloud storage"},{"id":"b","label":"Local storage"},{"id":"c","label":"DaaS"},{"id":"d","label":"IaaS"}],"prompt":"Saving a document only on the hard drive of one classroom PC (never uploaded) is mainly an example of:","questionId":"week-3-cloud-q2","sourceType":"single"},"id":"week-3-cloud-q2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"}],"id":"week-3-cloud-outline","metadata":{"activityType":"Teaching","difficulty":"standard","estimatedDurationMinutes":10,"href":null,"status":"available","summary":"Outline cloud computing as internet-delivered resources that can scale.","title":"What is cloud technology?","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"Local storage versus cloud"},"id":"week-3-local-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Local storage keeps files on a device you control in the room. Cloud storage keeps files on remote servers you reach over the internet."},"id":"week-3-local-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"categories":[{"id":"local","label":"Local storage"},{"id":"cloud","label":"Cloud storage"}],"feedback":{"correct":"Those matches look right.","incorrect":"Check the definition and try again."},"formative":true,"items":[{"correctCategoryId":"local","id":"l1","text":"A homework file saved only on a laptop hard drive"},{"correctCategoryId":"cloud","id":"l2","text":"Photos backed up to Google Drive or OneDrive"},{"correctCategoryId":"local","id":"l3","text":"Music stored only on a phone with airplane mode and no sync"},{"correctCategoryId":"cloud","id":"l4","text":"College email messages held on the provider's mail servers"},{"correctCategoryId":"local","id":"l5","text":"A spreadsheet on a USB stick that never uploads"},{"correctCategoryId":"cloud","id":"l6","text":"Shared team files in a browser-based document suite"}],"prompt":"Classify each example.","questionId":"week-3-local-q"},"id":"week-3-local-q","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"classification","version":"0.1.0"}],"id":"week-3-local-vs-cloud","metadata":{"activityType":"Classification","difficulty":"standard","estimatedDurationMinutes":10,"href":null,"status":"available","summary":"Classify examples as local storage or cloud storage.","title":"Local storage versus cloud","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"SaaS (Software as a Service)"},"id":"week-3-saas-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"SaaS is software you use through a browser or app. The provider runs and updates the application. You mainly manage your account, content and access rights."},"id":"week-3-saas-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"correctOptionId":"a","feedback":{"correct":"The email application is provided and managed for you. That is SaaS.","incorrect":"The email application is provided and managed for you. That is SaaS."},"formative":true,"options":[{"id":"a","label":"SaaS"},{"id":"b","label":"IaaS"},{"id":"c","label":"PaaS"},{"id":"d","label":"Only local storage with no provider"}],"prompt":"Using college email in a browser is closest to:","questionId":"week-3-saas-q1","sourceType":"single"},"id":"week-3-saas-q1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"The provider maintains the SaaS application. Customers focus on using it and managing their data access.","incorrect":"The provider maintains the SaaS application. Customers focus on using it and managing their data access."},"formative":true,"options":[{"id":"a","label":"Every learner must install the app updates on school servers"},{"id":"b","label":"The cloud provider"},{"id":"c","label":"The electricity company"},{"id":"d","label":"Nobody ever updates SaaS apps"}],"prompt":"In SaaS, who usually installs security updates for the application itself?","questionId":"week-3-saas-q2","sourceType":"single"},"id":"week-3-saas-q2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"}],"id":"week-3-saas","metadata":{"activityType":"Teaching","difficulty":"standard","estimatedDurationMinutes":10,"href":null,"status":"available","summary":"Outline Software as a Service with familiar examples.","title":"SaaS","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"IaaS (Infrastructure as a Service)"},"id":"week-3-iaas-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"IaaS rents infrastructure such as virtual machines, storage and networks. The customer installs and manages operating systems and software. The provider manages the physical data centre hardware."},"id":"week-3-iaas-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"Renting virtual servers and managing the software stack yourself is IaaS.","incorrect":"Renting virtual servers and managing the software stack yourself is IaaS."},"formative":true,"options":[{"id":"a","label":"SaaS"},{"id":"b","label":"IaaS"},{"id":"c","label":"DaaS"},{"id":"d","label":"A paper archive"}],"prompt":"An IT team rents virtual servers and then installs its own operating systems and apps. This is mainly:","questionId":"week-3-iaas-q1","sourceType":"single"},"id":"week-3-iaas-q1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"Scaling storage up and down is a common cloud benefit, often via infrastructure services.","incorrect":"Scaling storage up and down is a common cloud benefit, often via infrastructure services."},"formative":true,"options":[{"id":"a","label":"That cloud capacity cannot change"},{"id":"b","label":"That IaaS-style resources can scale with demand"},{"id":"c","label":"That only SaaS can use disks"},{"id":"d","label":"That local USB sticks are required"}],"prompt":"A college rents extra virtual disks during exam week, then scales down afterwards. This mainly shows:","questionId":"week-3-iaas-q2","sourceType":"single"},"id":"week-3-iaas-q2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"}],"id":"week-3-iaas","metadata":{"activityType":"Teaching","difficulty":"standard","estimatedDurationMinutes":10,"href":null,"status":"available","summary":"Outline Infrastructure as a Service: rented virtual machines, storage and networks.","title":"IaaS","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"PaaS (Platform as a Service)"},"id":"week-3-paas-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"PaaS gives a ready environment to build, test and run applications. The provider manages the platform. Developers focus on their app code rather than buying and patching every server."},"id":"week-3-paas-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"correctOptionId":"c","feedback":{"correct":"A hosted environment for building and running apps is PaaS.","incorrect":"A hosted environment for building and running apps is PaaS."},"formative":true,"options":[{"id":"a","label":"SaaS"},{"id":"b","label":"IaaS"},{"id":"c","label":"PaaS"},{"id":"d","label":"DaaS"}],"prompt":"Developers deploy an app into a hosted build-and-run environment. This is mainly:","questionId":"week-3-paas-q1","sourceType":"single"},"id":"week-3-paas-q1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"PaaS reduces how much infrastructure the customer manages so they can focus on the application.","incorrect":"PaaS reduces how much infrastructure the customer manages so they can focus on the application."},"formative":true,"options":[{"id":"a","label":"Must build the physical data centre"},{"id":"b","label":"Manages less of the underlying servers and focuses more on the application"},{"id":"c","label":"Can never write any code"},{"id":"d","label":"Only prints paper reports"}],"prompt":"Compared with IaaS, PaaS usually means the customer:","questionId":"week-3-paas-q2","sourceType":"single"},"id":"week-3-paas-q2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"}],"id":"week-3-paas","metadata":{"activityType":"Teaching","difficulty":"standard","estimatedDurationMinutes":10,"href":null,"status":"available","summary":"Outline Platform as a Service for building and running applications.","title":"PaaS","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"DaaS (Desktop as a Service)"},"id":"week-3-daas-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"DaaS delivers a desktop environment over the network. The user works on a remote desktop rather than relying only on software installed on one local PC."},"id":"week-3-daas-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"correctOptionId":"c","feedback":{"correct":"A full desktop session delivered remotely is Desktop as a Service (DaaS).","incorrect":"A full desktop session delivered remotely is Desktop as a Service (DaaS)."},"formative":true,"options":[{"id":"a","label":"SaaS document editing only"},{"id":"b","label":"IaaS bare-metal only"},{"id":"c","label":"DaaS"},{"id":"d","label":"A USB stick OS"}],"prompt":"Staff log in to a Windows desktop that runs in the cloud. This is mainly:","questionId":"week-3-daas-q1","sourceType":"single"},"id":"week-3-daas-q1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"a","feedback":{"correct":"DaaS provides a desktop session remotely over the network.","incorrect":"DaaS provides a desktop session remotely over the network."},"formative":true,"options":[{"id":"a","label":"A desktop environment delivered over the network"},{"id":"b","label":"A physical tower PC that cannot be accessed remotely"},{"id":"c","label":"Only a barcode scanner"},{"id":"d","label":"Only a printed timetable"}],"prompt":"DaaS is best outlined as:","questionId":"week-3-daas-q2","sourceType":"single"},"id":"week-3-daas-q2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"}],"id":"week-3-daas","metadata":{"activityType":"Teaching","difficulty":"standard","estimatedDurationMinutes":10,"href":null,"status":"available","summary":"Outline Desktop as a Service: a desktop session delivered over the network.","title":"DaaS","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"Match services to cloud models"},"id":"week-3-models-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Ask what you are buying: a ready app (SaaS), raw infrastructure (IaaS), an app platform (PaaS), or a remote desktop (DaaS)."},"id":"week-3-models-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"categories":[{"id":"saas","label":"SaaS"},{"id":"iaas","label":"IaaS"},{"id":"paas","label":"PaaS"},{"id":"daas","label":"DaaS"}],"feedback":{"correct":"Those matches look right.","incorrect":"Check the definition and try again."},"formative":true,"items":[{"correctCategoryId":"saas","id":"m1","text":"Learners write documents in a browser-based office suite"},{"correctCategoryId":"iaas","id":"m2","text":"An IT team rents virtual servers and installs its own software stack"},{"correctCategoryId":"paas","id":"m3","text":"Developers deploy an app into a hosted build-and-run environment"},{"correctCategoryId":"daas","id":"m4","text":"Staff log in to a Windows desktop that runs in the cloud"},{"correctCategoryId":"saas","id":"m5","text":"A class uses a hosted quiz tool with no local install"},{"correctCategoryId":"iaas","id":"m6","text":"A college rents extra virtual disks during exam week"},{"correctCategoryId":"saas","id":"m7","text":"College email opened in a browser"},{"correctCategoryId":"daas","id":"m8","text":"A remote desktop used from a thin client in a library"}],"prompt":"Classify each example.","questionId":"week-3-models-q"},"id":"week-3-models-q","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"classification","version":"0.1.0"}],"id":"week-3-models-match","metadata":{"activityType":"Classification","difficulty":"standard","estimatedDurationMinutes":14,"href":null,"status":"available","summary":"Classify everyday services as SaaS, IaaS, PaaS or DaaS.","title":"Match services to cloud models","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"Who manages what?"},"id":"week-3-resp-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"In cloud models, some jobs stay with the customer and some stay with the provider. The split changes across SaaS, IaaS, PaaS and DaaS."},"id":"week-3-resp-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"categories":[{"id":"customer","label":"Mainly the customer"},{"id":"provider","label":"Mainly the provider"}],"feedback":{"correct":"Those matches look right.","incorrect":"Check the definition and try again."},"formative":true,"items":[{"correctCategoryId":"customer","id":"r1","text":"Choosing strong passwords and careful sharing settings"},{"correctCategoryId":"provider","id":"r2","text":"Patching the email application on the provider servers"},{"correctCategoryId":"customer","id":"r3","text":"Deciding which classmates may edit a shared folder"},{"correctCategoryId":"provider","id":"r4","text":"Keeping the data centre power and cooling running"},{"correctCategoryId":"customer","id":"r5","text":"Writing the message content of your own emails"},{"correctCategoryId":"provider","id":"r6","text":"Updating the SaaS product features for all tenants"}],"prompt":"For a typical SaaS email service, classify each responsibility.","questionId":"week-3-resp-q"},"id":"week-3-resp-q","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"classification","version":"0.1.0"}],"id":"week-3-responsibility","metadata":{"activityType":"Classification","difficulty":"standard","estimatedDurationMinutes":12,"href":null,"status":"available","summary":"Classify responsibilities as mainly customer or mainly provider.","title":"Who manages what?","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"Which model fits?"},"id":"week-3-scen-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Read each scenario and pick the model that best matches what the organisation is buying."},"id":"week-3-scen-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"Ready-to-use apps with little server management point to SaaS.","incorrect":"Ready-to-use apps with little server management point to SaaS."},"formative":true,"options":[{"id":"a","label":"IaaS"},{"id":"b","label":"SaaS"},{"id":"c","label":"Only local hard drives"},{"id":"d","label":"DaaS physical towers only"}],"prompt":"A small charity wants staff to use email and shared docs without running its own mail servers. Best fit:","questionId":"week-3-scen-q1","sourceType":"single"},"id":"week-3-scen-q1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"Control of OS and software on rented machines is IaaS.","incorrect":"Control of OS and software on rented machines is IaaS."},"formative":true,"options":[{"id":"a","label":"SaaS"},{"id":"b","label":"IaaS"},{"id":"c","label":"Only paper records"},{"id":"d","label":"DaaS without any network"}],"prompt":"A college IT team wants full control of operating systems on rented virtual machines. Best fit:","questionId":"week-3-scen-q2","sourceType":"single"},"id":"week-3-scen-q2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"a","feedback":{"correct":"A ready build-and-run platform for developers is PaaS.","incorrect":"A ready build-and-run platform for developers is PaaS."},"formative":true,"options":[{"id":"a","label":"PaaS"},{"id":"b","label":"Only USB sticks"},{"id":"c","label":"Printed manuals"},{"id":"d","label":"Barcode-only systems"}],"prompt":"A start-up wants developers to deploy code quickly without building servers from scratch. Best fit:","questionId":"week-3-scen-q3","sourceType":"single"},"id":"week-3-scen-q3","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"a","feedback":{"correct":"A managed desktop delivered over the network is DaaS.","incorrect":"A managed desktop delivered over the network is DaaS."},"formative":true,"options":[{"id":"a","label":"DaaS"},{"id":"b","label":"Only a classroom whiteboard"},{"id":"c","label":"Local-only floppy disks"},{"id":"d","label":"NFC tags with no network"}],"prompt":"A business wants staff to open the same managed Windows desktop from home or campus. Best fit:","questionId":"week-3-scen-q4","sourceType":"single"},"id":"week-3-scen-q4","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"}],"id":"week-3-scenarios","metadata":{"activityType":"Knowledge check","difficulty":"standard","estimatedDurationMinutes":12,"href":null,"status":"available","summary":"Choose the best cloud model for each organisational scenario.","title":"Which model fits?","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"Benefits, dependencies and risks"},"id":"week-3-br-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Cloud can reduce on-site equipment needs and support scaling. It can also create dependency on a provider, internet access and good account security."},"id":"week-3-br-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"Scaling without constantly buying new local hardware is a common cloud benefit.","incorrect":"Scaling without constantly buying new local hardware is a common cloud benefit."},"formative":true,"options":[{"id":"a","label":"They never need internet access again"},{"id":"b","label":"They can often scale capacity without buying new on-site hardware every time"},{"id":"c","label":"Providers delete all customer data daily by default with no backup option"},{"id":"d","label":"Cloud always means zero cost"}],"prompt":"A clear benefit of cloud for many organisations is:","questionId":"week-3-br-q1","sourceType":"single"},"id":"week-3-br-q1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"Organisations depend on connectivity and the provider. Outages and lock-in are real risks to manage.","incorrect":"Organisations depend on connectivity and the provider. Outages and lock-in are real risks to manage."},"formative":true,"options":[{"id":"a","label":"No one ever needs a password"},{"id":"b","label":"Service outages or lock-in can affect work if the provider or internet link fails"},{"id":"c","label":"Paper printers stop existing"},{"id":"d","label":"USB sticks become illegal"}],"prompt":"A key dependency or risk of heavy cloud use is:","questionId":"week-3-br-q2","sourceType":"single"},"id":"week-3-br-q2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"formative":true,"guidance":"Write at least 300 characters. Mention one benefit and one dependency or risk. Paste is disabled.","minChars":300,"prompt":"Give one benefit of using cloud technology and one dependency or risk an organisation should manage.","questionId":"week-3-br-q3"},"id":"week-3-br-q3","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"short-response","version":"0.1.0"}],"id":"week-3-benefits-risks","metadata":{"activityType":"Knowledge check","difficulty":"standard","estimatedDurationMinutes":12,"href":null,"status":"available","summary":"Check benefits of cloud use and key dependencies or risks.","title":"Cloud benefits and dependencies","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"Organisational cloud example"},"id":"week-3-org-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Organisations use cloud services for email, storage, development platforms, virtual machines and remote desktops."},"id":"week-3-org-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"formative":true,"guidance":"Write at least 300 characters. Name the organisation, the model (SaaS, IaaS, PaaS or DaaS), and the purpose. Paste is disabled.","minChars":300,"prompt":"Name one organisation (real or realistic). State which cloud model it uses in your example and what the service is for.","questionId":"week-3-org-q"},"id":"week-3-org-q","metadata":{},