d.","minChars":250,"prompt":"In your own words, explain why a small business might choose SaaS rather than IaaS.","questionId":"week-3-ext-q2"},"id":"week-3-ext-q2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"short-response","version":"0.1.0"}],"id":"week-3-extension","metadata":{"activityType":"Extension","difficulty":"standard","estimatedDurationMinutes":10,"href":null,"status":"available","summary":"Explain why a small business might choose SaaS rather than IaaS.","title":"Extension: SaaS or IaaS for a small business?","topics":[]},"relationships":{"assets":[],"assignment":"formative-practice","learningOutcomes":["lo1"],"prerequisites":[],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":2,"text":"Cloud technology profile"},"id":"week-3-profile-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Independent task: build a short profile you could reuse when outlining technologies for AC1.1 practice. This is formative, not Gateway assignment evidence."},"id":"week-3-profile-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"formative":true,"guidance":"Cover service, model, who uses it, one benefit and one dependency or risk. Write at least 500 characters. Paste is disabled.","minChars":500,"prompt":"Write a cloud profile: name one cloud service, state whether it is closest to SaaS, IaaS, PaaS or DaaS, say who uses it, give one benefit, and give one dependency or risk.","questionId":"week-3-profile-q"},"id":"week-3-profile-q","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"reflection","version":"0.1.0"}],"id":"week-3-profile","metadata":{"activityType":"Reflection","difficulty":"standard","estimatedDurationMinutes":12,"href":nul