new and emerging digital technologies","route":"week-1/","status":"available","teachingWeek":1,"title":"Introduction to New and Emerging Digital Technologies"},"relationships":{"assignment":"formative-practice","curriculum":"l2e-exploring-emerging-digital-technologies-curriculum","learningOutcomes":["lo1"],"sessions":["week-1-session"]},"schema":"lp.content.week","schemaVersion":"0.1.0","version":"0.1.0"},{"id":"week-2","metadata":{"professionalPractice":"LO1 / AC 1.1 - outline IoT, connected devices, RFID, NFC and wearables","route":"week-2/","status":"available","teachingWeek":2,"title":"Internet of Things, RFID, NFC and Wearables"},"relationships":{"assignment":"formative-practice","curriculum":"l2e-exploring-emerging-digital-technologies-curriculum","learningOutcomes":["lo1"],"sessions":["week-2-session"]},"schema":"lp.content.week","schemaVersion":"0.1.0","version":"0.1.0"},{"id":"week-3","metadata":{"professionalPractice":"LO1 / AC 1.1 - outline cloud technology and service models (SaaS, IaaS, PaaS, DaaS)","route":"week-3/","status":"available","teachingWeek":3,"title":"Cloud Technology, SaaS, IaaS, PaaS and DaaS"},"relationships":{"assignment":"formative-practice","curriculum":"l2e-exploring-emerging-digital-technologies-curriculum","learningOutcomes":["lo1"],"sessions":["week-3-session"]},"schema":"lp.content.week","schemaVersion":"0.1.0","version":"0.1.0"}]}$l2e_pkg_0313$::jsonb;
  v_hash text := 'aa8a115dcbc1bae8fee8854a219bc072d2a760373cbcc2fde0281738195c971c';
  v_publication_id uuid;
  v_prev text;
  v_publisher uuid;
  v_staff_ref text;
begin
  select coalesce(
    (select id from auth.users where id = 'fd5fcbfc-5c01-4df3-a8df-458e1dbb0cc4'::uuid),
    (select id from auth.users order by created_at nulls last, id limit 1)
  ) into v_publisher;

  if v_publisher is null then
    raise notice 'L2E 0.3.13 publication skipped: no auth.users row for published_by';
  elsif not exists (
    select 1 from learning.courses
    where stable_key = 'gateway-level-2-digital-it-skills' and active
  ) then
    raise notice 'L2E 0.3.13 publication skipped: gateway course not present';
  elsif exists (
    select 1 from platform.curriculum_publications
    where hub_code = 'l2e-exploring-emerging-digital-technologies'
      and course_key = 'gateway-level-2-digital-it-skills'
      and package_version = '0.3.13'
  ) then
    raise notice 'L2E 0.3.13 already published';
  else
    v_staff_ref := 'PLATFORM-ADMIN-' || upper(replace(v_publisher::text, '-', ''));
    select package_version into v_prev
    from platform.curriculum_publications
    where hub_code = 'l2e-exploring-emerging-digital-technologies'
      and course_key = 'gateway-level-2-digital-it-skills'
      and status = 'published';

    update platform.curriculum_publications
    set status = 'superseded'
    where hub_code = 'l2e-exploring-emerging-digital-technologies'
      and course_key = 'gateway-level-2-digital-it-skills'
      and status = 'published';

    insert into platform.curriculum_publications (
      hub_code, course_key, package_version, schema_version, source_package_version,
      status, package, content_hash, author, reviewer, publication_notes,
      published_by_auth_user_id, published_by_staff_reference
    ) values (
      'l2e-exploring-emerging-digital-technologies',
      'gateway-level-2-digital-it-skills',
      '0.3.13',
      '0.1.0',
      '0.1.0',
      'published',
      v_package,
      v_hash,
      'L2E expanded Weeks 2-3 publication',
      'Curriculum review',
      format('Publish expanded L2E Weeks 1-3 package. Previous published version: %s', coalesce(v_prev, 'none')),
      v_publisher,
      v_staff_ref
    )
    returning id into v_publication_id;

    perform platform.project_curriculum_package(
      v_package,
      'l2e-exploring-emerging-digital-technologies',
      'gateway-level-2-digital-it-skills',
      '0.3.13',
      v_publication_id
    );
  end if;

  -- Assign every published L2E module activity version to the open delivery group.
  insert into learning.activity_assignments (
    id, group_id, activity_version_id, required, active
  )
  select
    md5(
      'l2e-delivery-activation:'
      || learner_group.id::text
      || ':'
      || activity_version.id::text
    )::uuid,
    learner_group.id,
    activity_version.id,
    true,
    true
  from learning.groups as learner_group
  join learning.courses as course on course.id = learner_group.course_id
  join learning.modules as module on module.course_id = course.id
  join learning.activities as activity on activity.module_id = module.id
  join learning.activity_versions as activity_version on activity_version.activity_id = activity.id
  where learner_group.code = 'L2E-DELIVERY-A'
    and course.stable_key = 'gateway-level-2-digital-it-skills'
    and module.stable_key = 'l2e-exploring-emerging-digital-technologies'
    and activity.active
    and activity_version.published_at is not null
    and activity_version.retired_at is null
  on conflict (group_id, activity_version_id) do update
  set required = excluded.required, active = excluded.active;
end
$$;
